/**
 * js/i18n.js — language engine
 *
 * One dictionary (data/ui-strings.json) drives two things:
 *   1. the in-page language toggle (this file)
 *   2. the English/Persian page pair generated by tools/build-fa-page.py
 *
 * index.html is English, fa.html is Persian. The toggle navigates between the
 * two and remembers the choice, so the URL stays shareable and search engines
 * still see a real Persian document.
 */
(function () {
  'use strict';

  var PAGE_LANG = (document.documentElement.getAttribute('lang') || 'en').toLowerCase().indexOf('fa') === 0 ? 'fa' : 'en';
  var STORAGE_KEY = 'portfolio-lang';
  var dict = { en: {}, fa: {} };
  var isFrame = false;
  try { isFrame = window.self !== window.top; } catch (error) { isFrame = true; }

  // Labels the scripts build themselves before the dictionary arrives. Kept
  // tiny on purpose: only what a first paint of a generated card needs.
  var FALLBACK = {
    en: {
      caseOpen: 'Open', caseKicker: 'CASE STUDY', brandKicker: 'BRAND', caseUntitled: 'Untitled project',
      caseUntitledBrand: 'Untitled brand', caseNoMedia: 'No media added yet.', casePrev: 'Previous media',
      caseNext: 'Next media', caseClient: 'Client', caseDeliverable: 'Deliverable', caseOutcome: 'Outcome',
      caseRole: 'Role', caseTools: 'Tools Used', caseWhy: 'WHY IT MATTERS & IMPACT',
      caseLive: 'Watch it where it was published', caseGallery: 'Media gallery',
      caseSelectedWork: 'Selected work', galleryOpen: 'Open media', lightboxTitle: 'Media',
      workEmptyTitle: 'I’m adding case studies here',
      workEmptyCopy: 'To discuss a similar brief, send me a short note.',
      workEmptyCta: 'Send the brief', ctaCardTitle: 'Your project next?',
      ctaCardSub: 'Tell me what the motion needs to explain — get a clear scope, price and timeline back.', ctaCardAction: 'Send the brief',
      countProjects: 'projects', countCases: 'case studies', countMedia: 'media',
      rateFeaturedBadge: 'MOST REQUESTED', rateAskPricing: 'Ask for a quote',
      journeyEmpty: 'Nothing added here yet.', tagCurrent: 'Current',
      serviceDefaultBullet1: 'Clear scope agreed before the first frame',
      serviceDefaultBullet2: 'Master files and web-ready exports',
      embedGate: 'This video is hosted on YouTube/Vimeo. Loading it sends your IP address to that provider.',
      loadVideo: 'Load video',
      workLoading: 'Loading work…', gridLoading: 'Loading…', resumeLabel: 'Client one-pager (PDF)',
      trackOneName: 'Product motion', trackTwoName: 'Explainer', stagePosterLabel: 'Motion reel',
      stageFileNameLabel: 'Motion reel preview'
    },
    fa: {
      caseOpen: 'نمایش', caseKicker: 'پروژه', brandKicker: 'برند', caseUntitled: 'پروژهٔ بدون عنوان',
      caseUntitledBrand: 'برند بدون نام', caseNoMedia: 'هنوز فایلی اضافه نشده است.', casePrev: 'فایل قبلی',
      caseNext: 'فایل بعدی', caseClient: 'کارفرما', caseDeliverable: 'تحویل', caseOutcome: 'نتیجه',
      caseRole: 'نقش من', caseTools: 'ابزارهای استفاده‌شده', caseWhy: 'چرا اهمیت دارد و نتیجهٔ کار',
      caseLive: 'کار را سر جایش ببینید', caseGallery: 'گالری فایل',
      caseSelectedWork: 'نمونه‌کارها', galleryOpen: 'بازکردن فایل', lightboxTitle: 'فایل',
      workEmptyTitle: 'نمونه‌های این بخش را طی روزهای آینده اضافه می‌کنم',
      workEmptyCopy: 'اگر برای کاری مشابه دنبال موشن هستید، هدف و زمان تحویل را کوتاه بنویسید.',
      workEmptyCta: 'ارسال بریف', ctaCardTitle: 'پروژهٔ بعدی از شما؟',
      ctaCardSub: 'بگویید موشن باید چه چیزی را نشان دهد تا شرح کار، قیمت و زمان‌بندی دقیق را بفرستم.', ctaCardAction: 'ارسال بریف',
      countProjects: 'پروژه', countCases: 'پروژه', countMedia: 'فایل',
      rateFeaturedBadge: 'پرتقاضاترین خدمت', rateAskPricing: 'استعلام قیمت',
      journeyEmpty: 'هنوز چیزی اضافه نشده است.', tagCurrent: 'همکاری فعلی',
      serviceDefaultBullet1: 'شرح کار روشن، پیش از اولین فریم',
      serviceDefaultBullet2: 'فایل مستر و خروجی آمادهٔ وب',
      embedGate: 'این ویدیو روی یوتیوب/ویمئو میزبانی می‌شود؛ با بازکردنش، IP شما برای آن سرویس ارسال می‌شود.',
      loadVideo: 'پخش ویدیو',
      workLoading: 'در حال بارگذاری نمونه‌کارها…', gridLoading: 'در حال بارگذاری…', resumeLabel: 'وان‌پیجر مشتری (PDF)',
      trackOneName: 'موشن محصول', trackTwoName: 'اکسپلینر', stagePosterLabel: 'ریل موشن',
      stageFileNameLabel: 'پیش‌نمایش ریل موشن'
    }
  };

  function t(key) {
    var pack = dict[PAGE_LANG] || {};
    if (pack[key] != null && pack[key] !== '') return pack[key];
    var en = dict.en || {};
    if (en[key] != null && en[key] !== '') return en[key];
    var fallback = FALLBACK[PAGE_LANG] || FALLBACK.en;
    if (fallback[key] != null) return fallback[key];
    return FALLBACK.en[key] != null ? FALLBACK.en[key] : key;
  }

  function otherPage() {
    return PAGE_LANG === 'fa' ? 'index.html' : 'fa.html';
  }

  function remembered() {
    try { return localStorage.getItem(STORAGE_KEY); } catch (error) { return null; }
  }

  function remember(lang) {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (error) { /* storage blocked: still navigates */ }
  }

  // Switch language. Same-language call just re-applies labels.
  function setLanguage(lang, options) {
    var next = lang === 'fa' ? 'fa' : 'en';
    var opts = options || {};
    if (next === PAGE_LANG) {
      applyLabels();
      return false;
    }
    if (opts.remember !== false) remember(next);
    var url = otherPage() + (window.location.hash || '');
    window.location.href = url;
    return true;
  }

  // Fill [data-i18n] / [data-i18n-placeholder] / [data-i18n-label] from the
  // dictionary for the page's own language. Static pages already ship the right
  // words; this keeps dynamically built markup and edits in step.
  function applyLabels(root) {
    var scope = root || document;
    scope.querySelectorAll('[data-i18n]').forEach(function (el) {
      var settingKey = el.getAttribute('data-setting');
      var settings = window.SiteSettings;
      if (settingKey && settings && (settings[settingKey] || (PAGE_LANG === 'fa' && settings[settingKey + 'Fa']))) return;
      var key = el.getAttribute('data-i18n');
      var value = t(key);
      if (value && value !== key) el.textContent = value;
    });
    scope.querySelectorAll('[data-i18n-placeholder]').forEach(function (el) {
      var value = t(el.getAttribute('data-i18n-placeholder'));
      if (value) el.setAttribute('placeholder', value);
    });
    scope.querySelectorAll('[data-i18n-label]').forEach(function (el) {
      var value = t(el.getAttribute('data-i18n-label'));
      if (value) el.setAttribute('aria-label', value);
    });
  }

  function applyDocumentLanguage() {
    var html = document.documentElement;
    html.setAttribute('lang', PAGE_LANG);
    html.setAttribute('dir', PAGE_LANG === 'fa' ? 'rtl' : 'ltr');
    var toggleLabel = document.getElementById('langToggleLabel');
    var toggle = document.getElementById('langToggle');
    if (toggleLabel) toggleLabel.textContent = t('langToggleLabel');
    if (toggle) {
      toggle.setAttribute('title', t('langToggleTitle'));
      toggle.setAttribute('aria-label', t('langToggleTitle'));
    }
    var themeToggle = document.getElementById('themeToggle');
    if (themeToggle) themeToggle.setAttribute('aria-label', t('themeToggleTitle'));
  }

  function wireToggle() {
    var toggle = document.getElementById('langToggle');
    if (!toggle) return;
    toggle.addEventListener('click', function () {
      setLanguage(PAGE_LANG === 'fa' ? 'en' : 'fa');
    });
  }

  // First visit on the "wrong" page for a visitor who already picked a
  // language: send them to the page they chose, once, and never fight them
  // again (the ?lang= and ?stay= flags break the loop).
  function honourPreference() {
    if (isFrame) return;
    var params = new URLSearchParams(window.location.search);
    if (params.has('lang')) {
      var explicit = params.get('lang') === 'fa' ? 'fa' : 'en';
      remember(explicit);
      if (explicit !== PAGE_LANG) {
        window.location.replace(otherPage() + (window.location.hash || ''));
        return;
      }
    }
    if (params.has('stay')) return;
    var stored = remembered();
    if (stored && stored !== PAGE_LANG && !params.has('lang')) {
      window.location.replace(otherPage() + '?stay=1' + (window.location.hash || ''));
    }
  }

  var ready = fetch('data/ui-strings.json', { cache: 'no-cache' })
    .then(function (response) { return response.ok ? response.json() : null; })
    .then(function (data) {
      if (data && data.en && data.fa) dict = data;
      applyDocumentLanguage();
      applyLabels();
      document.dispatchEvent(new CustomEvent('site:labels'));
      return dict;
    })
    .catch(function () { return dict; });

  applyDocumentLanguage();
  wireToggle();

  window.SiteI18n = {
    lang: PAGE_LANG,
    otherPage: otherPage,
    t: t,
    dict: function () { return dict; },
    setLanguage: setLanguage,
    applyLabels: applyLabels,
    ready: ready
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { applyLabels(); });
  } else {
    applyLabels();
  }

  if (!document.documentElement.hasAttribute('data-no-redirect')) honourPreference();
})();
